"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7536],{11402:e=>{e.exports=JSON.parse('{"functions":[{"name":"validate","desc":"Validates `value` and returns a deep copy of it.","params":[{"name":"value","desc":"","lua_type":"any"},{"name":"budget","desc":"Maximum estimated encoded size, in bytes.","lua_type":"number"}],"returns":[{"desc":"Whether the value is storable.","lua_type":"boolean"},{"desc":"The copy, when valid.","lua_type":"any"},{"desc":"What was wrong and where, when not.","lua_type":"string?"}],"function_type":"static","source":{"line":126,"path":"src/internal/Serialize.luau"}},{"name":"size","desc":"The estimated encoded size of an already-validated value. Used to decide\\nwhether a match envelope fits inside a broadcast payload.","params":[{"name":"value","desc":"","lua_type":"any"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":148,"path":"src/internal/Serialize.luau"}}],"properties":[],"types":[],"name":"Serialize","desc":"Validates and copies consumer data on its way into a stored record.\\n\\nDeliberately hand-written rather than `HttpService:JSONEncode`: it must\\nbehave identically under Lune and in Studio, it must report *which* field is\\nthe problem, and it must be able to stop early once a value is obviously\\nover budget. It also copies, so a consumer mutating their table after\\nreturning it cannot alter a match that has already been committed.\\n\\nRejected: functions, userdata (Instances, Vector3, Color3, ...), threads,\\ncycles, NaN and infinity, non-string/number keys, tables mixing array and\\nhash keys, and anything nested deeper than `Defaults.MAX_DATA_DEPTH`. Every\\none of those either fails to survive MemoryStore\'s JSON round trip or comes\\nback a different shape than it went in.","source":{"line":20,"path":"src/internal/Serialize.luau"}}')}}]);